import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.KobcctIO.js";const k=JSON.parse('{"title":"Atomic Locks and Data Integrity Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/horizon/locks-and-security.md","filePath":"guide/horizon/locks-and-security.md"}'),t={name:"guide/horizon/locks-and-security.md"};function o(l,s,r,p,c,h){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="atomic-locks-and-data-integrity-security" tabindex="-1">Atomic Locks and Data Integrity Security <a class="header-anchor" href="#atomic-locks-and-data-integrity-security" aria-label="Permalink to &quot;Atomic Locks and Data Integrity Security&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Concurrency-Atomic%20Lock%20%2B%20Heartbeat-blue.svg" alt="Concurrency"><img src="https://img.shields.io/badge/Safety-Anti--Zip%20Slip-green.svg" alt="Anti-Zip Slip"><img src="https://img.shields.io/badge/Recovery-Deterministic%20Rollback-orange.svg" alt="Recovery"></div><p>In a multi-device setup where distinct computers can access the same cloud instance profile, preventing state corruption, race conditions, and unsafe archive decompression is paramount.</p><hr><h2 id="_1-atomic-lockfile-protocol-lock-js" tabindex="-1">1. Atomic Lockfile Protocol (<code>lock.js</code>) <a class="header-anchor" href="#_1-atomic-lockfile-protocol-lock-js" aria-label="Permalink to &quot;1. Atomic Lockfile Protocol (\`lock.js\`)&quot;">​</a></h2><p>To prevent two synchronization sessions from running concurrently on the same Minecraft directory, Gens-Horizon enforces an atomic physical lockfile protocol:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Synchronization Starts ]</span></span>
<span class="line"><span>            |</span></span>
<span class="line"><span>            v</span></span>
<span class="line"><span>    Attempt atomic creation:</span></span>
<span class="line"><span>    fs.open(&#39;horizon.lock&#39;, O_CREAT | O_EXCL)</span></span>
<span class="line"><span>            |</span></span>
<span class="line"><span>     +------+------+</span></span>
<span class="line"><span>     |             |</span></span>
<span class="line"><span> [ SUCCESS ]   [ FAILURE (EEXIST) ]</span></span>
<span class="line"><span>     |             |</span></span>
<span class="line"><span>     |             v</span></span>
<span class="line"><span>     |    Inspect Existing Lock:</span></span>
<span class="line"><span>     |    - Is the master PID still alive? (kill(pid, 0))</span></span>
<span class="line"><span>     |    - Has the lock been silent for &gt; 2 hours? (STALE_LOCK_MS)</span></span>
<span class="line"><span>     |             |</span></span>
<span class="line"><span>     |      +------+------+</span></span>
<span class="line"><span>     |      |             |</span></span>
<span class="line"><span>     |  [ ACTIVE ]   [ ORPHAN / DEAD ]</span></span>
<span class="line"><span>     |      |             |</span></span>
<span class="line"><span>     |   Concurrency      v</span></span>
<span class="line"><span>     |   Abort       Purge stale lock</span></span>
<span class="line"><span>     |   (Stop)      &amp; recreate</span></span>
<span class="line"><span>     |                    |</span></span>
<span class="line"><span>     +--------------------+</span></span>
<span class="line"><span>            |</span></span>
<span class="line"><span>            v</span></span>
<span class="line"><span>[ Active Heartbeat Loop every 5 seconds ]</span></span>
<span class="line"><span>fs.promises.utimes(&#39;horizon.lock&#39;)</span></span>
<span class="line"><span>            |</span></span>
<span class="line"><span>            v</span></span>
<span class="line"><span>[ Synchronization Finishes: Unlink horizon.lock ]</span></span></code></pre></div><h3 id="the-5-second-heartbeat" tabindex="-1">The 5-Second Heartbeat <a class="header-anchor" href="#the-5-second-heartbeat" aria-label="Permalink to &quot;The 5-Second Heartbeat&quot;">​</a></h3><p>Throughout the lifecycle of a synchronization operation (scanning, compression, network transfer), the master process touches the modification time (<code>mtimeMs</code>) of <code>horizon.lock</code> every 5 seconds.</p><h3 id="stale-lock-detection" tabindex="-1">Stale Lock Detection <a class="header-anchor" href="#stale-lock-detection" aria-label="Permalink to &quot;Stale Lock Detection&quot;">​</a></h3><p>If an unexpected shutdown or hard kill (<code>SIGKILL</code>) leaves <code>horizon.lock</code> lingering on disk, Gens-Horizon evaluates lock status on its next launch:</p><ol><li><strong>Process Liveness Test (<code>process.kill(pid, 0)</code>):</strong> If the OS confirms the PID no longer exists (<code>ESRCH</code>), the lock is declared orphaned and purged immediately.</li><li><strong>Inactivity Threshold (2 Hours):</strong> Even if the PID was subsequently reassigned to another unrelated OS task, a lock whose heartbeat has not updated for over 2 hours (<code>STALE_LOCK_MS = 7200000</code>) is automatically discarded.</li></ol><h3 id="process-coupling-with-gens-launcher-ipc-horizon-js" tabindex="-1">Process Coupling with Gens-Launcher (<code>ipc-horizon.js</code>) <a class="header-anchor" href="#process-coupling-with-gens-launcher-ipc-horizon-js" aria-label="Permalink to &quot;Process Coupling with Gens-Launcher (\`ipc-horizon.js\`)&quot;">​</a></h3><p>The parent launcher reads <code>mtimeMs</code> of <code>horizon.lock</code> before permitting cloud interactions in the GUI. Lock parameters (5s heartbeat interval and 2h stale threshold) are strictly aligned across both repositories.</p><hr><h2 id="_2-secure-archive-extraction-and-zip-slip-defenses-zip-utils-js" tabindex="-1">2. Secure Archive Extraction and Zip Slip Defenses (<code>zip-utils.js</code>) <a class="header-anchor" href="#_2-secure-archive-extraction-and-zip-slip-defenses-zip-utils-js" aria-label="Permalink to &quot;2. Secure Archive Extraction and Zip Slip Defenses (\`zip-utils.js\`)&quot;">​</a></h2><p>Decompressing remote zip archives carries inherent risks if an archive contains malicious relative paths (such as <code>../../../../Windows/System32</code>). Gens-Horizon mitigates this threat:</p><ol><li><strong>Extraction Path Boundary Inspection:</strong><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> resolvedTarget</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> path.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(destDir);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> resolvedDest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> path.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(destDir, entry.fileName);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resolvedDest.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">startsWith</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(resolvedTarget </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> path.sep) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resolvedDest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resolvedTarget) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    throw</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`Zip Slip security violation: \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">entry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fileName</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><strong>Binary Signature Verification:</strong> Before initiating decompression, the engine confirms the presence of the standard ZIP magic header <code>0x504B0304</code> (<code>PK\\x03\\x04</code>) and verifies that the Central Directory is readable.</li><li><strong>Stream Decompression via <code>yauzl</code>:</strong> Extraction streams data on the fly rather than buffering the entire archive into memory, ensuring stability on large modpack archives.</li></ol><hr><h2 id="_3-deterministic-historical-rollback-rollback-js" tabindex="-1">3. Deterministic Historical Rollback (<code>rollback.js</code>) <a class="header-anchor" href="#_3-deterministic-historical-rollback-rollback-js" aria-label="Permalink to &quot;3. Deterministic Historical Rollback (\`rollback.js\`)&quot;">​</a></h2><p>If a world save is damaged by gameplay errors or a faulty mod:</p><ul><li>Each cloud synchronization session creates a unique historical snapshot identified by its timestamp and manifest hash.</li><li>Running <code>--rollback --instance &quot;Name&quot; --target &quot;&lt;timestamp&gt;&quot;</code> reconstructs the exact directory structure as it existed at that precise moment by chronologically reverting or replaying deltas.</li></ul>`,22)])])}const g=a(t,[["render",o]]);export{k as __pageData,g as default};
